using System;using System.IO;using System.Linq;using System.Threading;using System.Text;
class ArchiveIndexTests{
 static void Check(bool pass,string name){if(!pass)throw new Exception(name);Console.WriteLine("PASS "+name);}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);var store=new ArchiveStore(root);var server=new Server{Host="index.fixture",User="qa",Port=22};var now=DateTime.UtcNow;var hour=new DateTime(now.Year,now.Month,now.Day,now.Hour,0,0,DateTimeKind.Utc);string folder=store.Folder(server);Directory.CreateDirectory(folder);string file=Path.Combine(folder,hour.ToString("yyyyMMdd-HH")+"-000.aqlog");var rec=ArchiveRecord.From(new Metrics{Cpu="10%",Mem="100 / 200 MiB"},hour.AddSeconds(10),2);string one=ArchiveStore.Json().Serialize(rec);Func<ArchiveResult> query=()=>store.Query(server,hour,hour.AddHours(1),CancellationToken.None);
 File.WriteAllText(file,one+"\r\n",new UTF8Encoding(true));var first=query();Check(first.Points.Count==1&&store.Read(first.Points[0]).T==rec.T,"BOM CRLF byte offsets");Check(query().Points.Count==1,"warm index");
 rec.T+=TimeSpan.TicksPerSecond;string two=ArchiveStore.Json().Serialize(rec);File.AppendAllText(file,two+"\n",new UTF8Encoding(false));var appended=query();Check(appended.Points.Count==2&&store.Read(appended.Points[1]).T==rec.T,"incremental append and offsets");
 rec.T+=TimeSpan.TicksPerSecond;string three=ArchiveStore.Json().Serialize(rec);File.AppendAllText(file,three.Substring(0,three.Length/2),new UTF8Encoding(false));Check(query().Points.Count==2&&query().Skipped==0,"incomplete last record is retryable");File.AppendAllText(file,three.Substring(three.Length/2)+"\n",new UTF8Encoding(false));Check(query().Points.Count==3,"completed partial record appears exactly once");
 File.AppendAllText(file,"{broken}\n",new UTF8Encoding(false));Check(query().Skipped==1&&query().Skipped==1,"malformed terminated line count stable");
 var cancelled=new CancellationTokenSource();cancelled.Cancel();bool stopped=false;try{store.Query(server,hour,hour.AddHours(1),cancelled.Token);}catch(OperationCanceledException){stopped=true;}Check(stopped&&query().Points.Count==3,"cancellation leaves valid cache");
 File.WriteAllText(file,two,new UTF8Encoding(false));Check(query().Points.Count==1&&store.Read(query().Points[0]).T==rec.T-TimeSpan.TicksPerSecond,"truncation rebuilds and unterminated complete JSON remains readable");
 File.WriteAllText(file,one,new UTF8Encoding(false));File.SetLastWriteTimeUtc(file,DateTime.UtcNow.AddSeconds(2));Check(query().Points[0].T==rec.T-2*TimeSpan.TicksPerSecond,"same length rewrite invalidation");
 string external=Path.Combine(root,"export.aqhistory");var head=ArchiveHeader.From(server);File.WriteAllText(external,ArchiveStore.Json().Serialize(head)+"\n"+one+"\n",new UTF8Encoding(false));var imported=store.Query(server,hour,hour.AddHours(1),CancellationToken.None,external);Check(imported.Points.Count==1&&store.Read(imported.Points[0]).T==imported.Points[0].T,"imported header and offsets");
 File.Delete(file);Check(query().Points.Count==0,"deleted archive never returned from stale cache");Console.WriteLine("ARCHIVE_INDEX_TESTS=PASS");
 }}